<?php require_once __DIR__ . '/../config/app.php'; require_admin(); ?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tambah Denda</title><link rel="stylesheet" href="<?= h(app_url('asset/app.css')) ?>"></head><body><main class="form-page"><section class="form-card"><a class="back-link" href="<?= h(app_url('controllers/c_denda.php')) ?>">← Kembali ke denda</a><p class="eyebrow">ADMINISTRATOR</p><h1>Tambah Denda</h1><p class="muted">Pilih peminjaman yang sudah dikembalikan. Setiap jenis denda hanya dapat dicatat sekali untuk satu peminjaman.</p>
<?php if (!$pinjam): ?><div class="notice">Belum ada peminjaman yang sudah dikembalikan untuk dicatat dendanya.</div><?php endif; ?>
<form method="post" action="<?= h(app_url('controllers/c_denda.php?aksi=simpan')) ?>" class="stack"><label>Peminjaman yang dikembalikan<select name="id_pinjam" required><option value="">-- Pilih peminjaman --</option><?php foreach ($pinjam as $p): ?><option value="<?= (int)$p->id_pinjam ?>">#<?= (int)$p->id_pinjam ?> · <?= h($p->nama_pengguna) ?> · <?= h($p->nama_buku) ?> · <?= h($p->tanggal_kembali) ?></option><?php endforeach; ?></select></label><label>Jenis Denda<select name="jenis_denda" id="jenis-denda" required><option value="Terlambat Mengembalikan Buku">Terlambat Mengembalikan Buku</option><option value="Kerusakan">Kerusakan</option><option value="Hilang">Hilang</option></select></label><label>Jumlah Hari Keterlambatan<input type="number" name="jumlah_hari_keterlambatan" id="hari" min="0" value="1" required></label><label>Jumlah Denda (Rp)<input type="number" name="jumlah_denda" id="jumlah" min="0" step="1000" value="<?= DENDA_PER_HARI ?>"></label><p class="muted small">Untuk keterlambatan, jumlah denda dihitung otomatis: jumlah hari × Rp<?= number_format(DENDA_PER_HARI,0,',','.') ?>. Untuk kerusakan atau hilang, isi nominal secara manual.</p><button class="btn btn-primary" type="submit" <?= !$pinjam ? 'disabled' : '' ?>>Simpan Denda</button><?= csrf_field() ?></form></section></main><script>const type=document.getElementById('jenis-denda'),days=document.getElementById('hari'),amount=document.getElementById('jumlah');function calc(){if(type.value==='Terlambat Mengembalikan Buku'){amount.value=Math.max(0,Number(days.value))*<?= DENDA_PER_HARI ?>;amount.readOnly=true;}else{amount.readOnly=false;}}type.addEventListener('change',calc);days.addEventListener('input',calc);calc();</script></body></html>
